import{z as o,x as n,o as e,c as B,q as E,j as s,D as t,d as A,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"HJM","description":"","frontmatter":{"title":"HJM","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hjm.md","filePath":"quant/hjm.md","lastUpdated":1791413859000}'),p={name:"quant/hjm.md"};function m(h,a,d,T,M,u){const i=n("Mermaid");return e(),B("div",null,[a[2]||(a[2]=E('<h1 id="hjm" tabindex="-1">HJM <a class="header-anchor" href="#hjm" aria-label="Permalink to &quot;HJM&quot;">​</a></h1><div class="epigraph"><p>直接写瞬时远期曲线的扩散，无套利会把漂移钉成波动的积分；期限结构模型不必再从短期利率出发。</p><footer>—— Heath, Jarrow &amp; Morton, Bond Pricing and the Term Structure of Interest Rates: A New Methodology, Econometrica, 1992</footer></div><p>Heath、Jarrow 与 Morton（1992）把状态从短期利率换成整条瞬时远期曲线 \\(f(t,T)\\)。一旦指定波动结构 \\(\\sigma(t,T)\\)，风险中性漂移不再自由：它必须等于波动沿到期轴的积分，否则折现债券会出现套利。短端模型——<a href="/quant/vasicek-cir">Vasicek / CIR</a>、<a href="/quant/hull-white">Hull-White</a>——成为特定波动下的马尔可夫特例。HJM 是框架，不是某一个校准好的三参数公式。本篇写漂移条件从哪来、为何实现往往要落到有限因子、以及它与 <a href="/quant/lmm">LMM</a> 在状态变量上的分工：一个写瞬时远期，一个写简单复利的市场利率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无套利定价要求可交易的零息债在折现后是鞅。若你只规定短端 \\(r_t\\) 的漂移与波动，整条曲线由短端的条件期望生成，形态被马尔可夫状态绑死。若你反过来让每个 \\(T\\) 的 \\(f(t,T)\\) 自由扩散，参数过多，任意漂移会产生与债券交易矛盾的关系。HJM 要回答：在曲线本身作为无限维状态时，哪些波动是允许的，漂移必须满足什么函数方程，才能让 \\(P(t,T)=\\exp\\big(-\\int_t^T f(t,u)\\,du\\big)\\) 在风险中性测度下表现正常。</p><p>这个问题的实践版本是：交易台已经看到整条曲线，不想用短端模型再拟合一次初值；他们想规定的是<strong>曲线如何动</strong>（主成分、关键利率波动），而不是短端均值回复速度。HJM 把「如何动」写成 \\(\\sigma(t,T)\\)，把无套利写成对漂移的约束。剩下的工程问题是无限维状态如何模拟、如何避免负利率、如何接到可观测的 cap 与 swaption。</p><h3 id="瞬时远期不是报价" tabindex="-1">瞬时远期不是报价 <a class="header-anchor" href="#瞬时远期不是报价" aria-label="Permalink to &quot;瞬时远期不是报价&quot;">​</a></h3><p>\\(f(t,T)\\) 是模型对象，市场给的是 LIBOR、SOFR 期货、互换与债券。从报价到 \\(f\\) 要经过曲线构建与平滑，微分会放大噪声。HJM 的漂移条件对 \\(f\\) 的光滑性敏感：波动若在 \\(T\\) 上不连续，漂移积分仍可定义，但实现时要把曲线与波动投到同一套关键点上。不要把 HJM 写成「直接对市场报价做扩散」——那是 LMM 的动机。HJM 先抽象到瞬时远期，再谈离散实现。</p><p><span class="marginnote">数字实例：零息利率是瞬时远期的平均。若 1 年零息利率是 3%、2 年是 3.5%，则 \\(2\\times 3.5\\%-1\\times 3\\%=4\\%\\) 就是「从第 1 年末借到第 2 年末」被远期锁定的利率。HJM 建模的对象就是这条逐点远期曲线 \\(f(t,T)\\) 本身，而不是某个期限的平均值。</span></p><p><span class="marginnote">HJM 的「无套利」是相对已经纳入模型的零息债族而言。若贴现曲线与预测曲线分离，或存在便利收益与回购特殊，单一 \\(f(t,T)\\) 不够。框架可以推广到多曲线，但 1992 年论文是单曲线的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 \\(d\\) 维布朗运动下，</p> \\[df(t,T)=\\alpha(t,T)\\,dt+\\sigma(t,T)^\\top dW_t, \\]<p>短端 \\(r_t=f(t,t)\\)。债券 \\(P(t,T)\\) 的扩散由 \\(\\sigma\\) 沿 \\([t,T]\\) 积分得到。要求折现债券为鞅，必须</p> \\[\\alpha(t,T)=\\sigma(t,T)^\\top\\int_t^T \\sigma(t,u)\\,du \\]<p>（风险中性；远期测度下还有计价物调整）。这就是 HJM 漂移条件：波动自由，漂移被波动决定。一因子高斯且 \\(\\sigma(t,T)=\\sigma e^{-a(T-t)}\\) 时，短端正是 Hull–White；\\(\\sigma\\) 常数且无衰减时接近 Ho–Lee。波动若依赖曲线本身，可得到类似 CIR 的正利率结构，但一般失去有限维马尔可夫。</p><p><span class="marginnote">常见误区：初学者容易把 HJM 当成和 Hull–White 平行的另一族模型。实际方向刚好相反——HJM 是大框架，Hull–White 是它在 \\(\\sigma(t,T)=\\sigma e^{-a(T-t)}\\) 这一种波动形态下的特例。就像「轿车」是某一种「车」：选了 HJM 波动再选指数衰减，你得到的就是 Hull–White，不是新东西。</span></p><p>实现上必须截断。常用：取 \\(d=2\\) 或 \\(3\\) 个因子，让 \\(\\sigma_i(t,T)\\) 对应平行、斜率、曲率；或把曲线降到有限个关键利率，对关键点做 HJM。模拟用预测器–校正器处理漂移里的积分。欧式权可用远期测度把被定价资产写成鞅再做 Black 型积分；美式与路径依赖仍要在曲线状态上做树或回归 Monte Carlo，维数诅咒立刻出现——这是短端马尔可夫模型仍然活着的原因。</p><h3 id="测度与计价物" tabindex="-1">测度与计价物 <a class="header-anchor" href="#测度与计价物" aria-label="Permalink to &quot;测度与计价物&quot;">​</a></h3><p>同一 \\(\\sigma\\) 在即期风险中性、到期 \\(T\\) 的远期测度、年金测度下漂移不同。HJM 条件通常先在风险中性下写出，再换测度给 caplet 或 swaption 减方差。Jamshidian 对一因子短端的分解在高维 HJM 里不再免费。工程上应先固定计价物，再写离散漂移，不要在风险中性下模拟折现因子路径却用远期测度的 Black 公式混在同一条书里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>漂移条件的机制是伊藤乘积：债券是远期的指数积分，债券的波动是 \\(\\sigma\\) 的积分，无套利要求债券的超额收益等于波动乘以风险的市场价格；风险中性下市场价格为零，于是远期的漂移只能由这段波动积分产生。直观上，波动越大、到期越长，凸性调整越大，远期的风险中性漂移越正——与「长端利率含凸性」同一件事，只是现在对每个 \\(T\\) 都写清楚了。</p><p><span class="marginnote">直觉类比：波动决定漂移，像骑自行车转弯必须倾斜。车身怎么倾（波动结构 \\(\\sigma\\)）一旦选定，为了不摔倒（无套利），车把怎么打（漂移 \\(\\alpha\\)）就被钉死了。HJM 的全部魔法就是这一句话：波动是自由输入，漂移不是。</span></p>',23)),(e(),s(l,null,{default:t(()=>[r(i,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22%E8%BF%9C%E6%9C%9F%20f(t%2CT)%20%E5%B8%A6%E6%B3%A2%E5%8A%A8%20%CF%83%22%5D%20--%3E%20B%5B%22%E5%80%BA%E5%88%B8%20P%20%E6%98%AF%20f%20%E7%9A%84%E6%8C%87%E6%95%B0%E7%A7%AF%E5%88%86%22%5D%0A%20%20B%20--%3E%20BV%5B%22%E5%80%BA%E5%88%B8%E6%B3%A2%E5%8A%A8%20%3D%20%CF%83%20%E6%B2%BF%20%5Bt%2CT%5D%20%E7%9A%84%E7%A7%AF%E5%88%86%22%5D%0A%20%20BV%20--%3E%20ITO%5B%22%E4%BC%8A%E8%97%A4%E4%B9%98%E7%A7%AF%EF%BC%9A%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%20%3D%20%E6%B3%A2%E5%8A%A8%20%C3%97%20%E9%A3%8E%E9%99%A9%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20ITO%20--%3E%20Q%5B%22%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%E6%B5%8B%E5%BA%A6%E4%B8%8B%E9%A3%8E%E9%99%A9%E4%BB%B7%E6%A0%BC%20%3D%200%22%5D%0A%20%20Q%20--%3E%20DR%5B%22%E6%BC%82%E7%A7%BB%E8%A2%AB%E8%BF%AB%E7%AD%89%E4%BA%8E%E6%B3%A2%E5%8A%A8%E7%A7%AF%E5%88%86%22%5D%0A%20%20DR%20--%3E%20CONV%5B%22%E6%B3%A2%E5%8A%A8%E8%B6%8A%E5%A4%A7%20%E2%86%92%20%E5%87%B8%E6%80%A7%E8%B0%83%E6%95%B4%E8%B6%8A%E5%A4%A7%20%E2%86%92%20%E6%BC%82%E7%A7%BB%E8%B6%8A%E6%AD%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>因子结构决定曲线能做哪些独立运动。一个因子：所有 \\(T\\) 的冲击完全相关，形状由 \\(\\sigma(\\cdot,T)\\) 的衰减描述。两个因子：可以分开水平和斜率。经验主成分告诉你三个因子已解释大部分日度变动，但期权要的是在风险中性下的波动，不是历史 PCA；把历史特征向量直接当 \\(\\sigma\\) 会把 \\(\\mathbb{P}\\) 的相关当成 \\(\\mathbb{Q}\\) 的波动，smile 与风险溢价被丢掉。</p><p><span class="marginnote">HJM 不自动保证正的简单利率。高斯 HJM 与高斯短端一样会负。要正利率，需对 \\(\\sigma\\) 加结构（比例于 \\(f\\) 或位移），这往往破坏有限马尔可夫，把你推向 LMM 那种对市场利率直接建模的离散框架。</span></p><h3 id="与短端模型的包含关系" tabindex="-1">与短端模型的包含关系 <a class="header-anchor" href="#与短端模型的包含关系" aria-label="Permalink to &quot;与短端模型的包含关系&quot;">​</a></h3><p>凡马尔可夫短端扩散，都对应某种 HJM 波动：由债券公式对 \\(T\\) 求导得到 \\(f\\)，再读出 \\(\\sigma(t,T)\\)。反过来，任意 \\(\\sigma(t,T)\\) 一般不能写成有限个短端状态的函数。因此「用 HJM」在实践中几乎总是「选一个能落到低维马尔可夫的 \\(\\sigma\\)」或「接受高维模拟」。宣称实现了一般 HJM 却只用一棵短端树，只是在做 Hull–White。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在未平滑的 bootstrap 曲线上对 \\(T\\) 做数值微分来驱动 HJM 漂移，尖刺会变成虚假的凸性交易。不要用三因子历史 PCA 校准后，就认为 Bermudan swaption 的行权溢价已经被解释——美式溢价还依赖波动的期限结构和均值回复（衰减）。不要把 HJM 与「无模型」混淆：\\(\\sigma\\) 的函数形式就是模型。</p><p>LIBOR 停用之后，瞬时远期更应建在 OIS / SOFR 贴现曲线上；期限利率期货有凸性与合成基差，不能当作 \\(f(t,T)\\) 的直接观察。高维 HJM 的计算成本通常高于 LMM 对标准 cap/swaption 账簿，因为 LMM 的状态就是那些被报价的远期。HJM 的优势在需要连续到期、债券期权、或把短端模型嵌进统一漂移语言的时候。选择框架先于选择因子个数。</p><p><span class="marginnote">漂移条件是局部的、逐日的无套利，不是「模型能预测收益率曲线」。HJM 对预期假说保持沉默：\\(\\mathbb{P}\\) 下的漂移还要加风险溢价，那是资产定价，不是衍生品记账。</span></p>',8)),(e(),s(l,null,{default:t(()=>[r(i,{id:"mermaid-88",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%8C%87%E5%AE%9A%E6%B3%A2%E5%8A%A8%20%CF%83(t%2CT)%22%5D%20--%3E%20DR%5B%22HJM%3A%20%CE%B1%20%3D%20%CF%83%20%C2%B7%20%E2%88%AB%CF%83%22%5D%0A%20%20DR%20--%3E%20F%5B%22%E6%95%B4%E6%9D%A1%E7%9E%AC%E6%97%B6%E8%BF%9C%E6%9C%9F%20f(t%2CT)%22%5D%0A%20%20F%20--%3E%20P%5B%22%E9%9B%B6%E6%81%AF%E5%80%BA%20P(t%2CT)%22%5D%0A%20%20SIG%20--%3E%20FAC%5B%22%E6%9C%89%E9%99%90%E5%9B%A0%E5%AD%90%20%2F%20%E5%85%B3%E9%94%AE%E5%88%A9%E7%8E%87%E6%88%AA%E6%96%AD%22%5D%0A%20%20FAC%20--%3E%20MC%5B%22%E6%A8%A1%E6%8B%9F%E4%B8%8E%E7%BE%8E%E5%BC%8F%22%5D%0A%20%20SIG%20--%3E%20SP%5B%22%E6%8C%87%E6%95%B0%E8%A1%B0%E5%87%8F%20%CF%83%20%E2%86%92%20Hull-White%22%5D%0A%20%20F%20--%3E%20DISC%5B%22%E7%A6%BB%E6%95%A3%E5%88%B0%E7%AE%80%E5%8D%95%E8%BF%9C%E6%9C%9F%20%E2%86%92%20LMM%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HJM（1992）对瞬时远期曲线建模；无套利把漂移写成波动沿到期的积分。</li><li>波动结构是自由输入；短端高斯模型是特定 \\(\\sigma(t,T)\\) 下的马尔可夫特例。</li><li>一般 HJM 是无限维的，实现必须有限因子化或关键利率化，否则美式无法算。</li><li>高斯 HJM 不保证正利率；正利率与市场报价对齐往往导向 LMM。</li><li>历史主成分可以提示因子形状，但不能替代风险中性波动校准。</li><li>出处：Heath, Jarrow &amp; Morton, <em>Econometrica</em>, 1992；与短端关系见 Björk 的讲义传统及 Hull–White 作为指数波动特例。</li></ul>',2))])}const H=o(p,[["render",m]]);export{C as __pageData,H as default};
